package perfdata

import (
	"bytes"
	"encoding/binary"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func sample(t testing.TB, name string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", name+".hsperf"))
	if err != nil {
		t.Fatal(err)
	}
	return data
}

// samples lists the files generated by testdata/generate.sh with the version
// each one must report.
var samples = []struct {
	name, version, collector string
}{
	{"jdk8-parallel", "1.8.0_", "PSScavenge"},
	{"jdk8-g1", "1.8.0_", "G1 incremental collections"},
	{"jdk8-serial", "1.8.0_", "Copy"},
	{"jdk8-cms", "1.8.0_", "PCopy"},
	{"jdk11-g1", "11.0.", "G1 incremental collections"},
	{"jdk11-parallel", "11.0.", "PSScavenge"},
	{"jdk11-serial", "11.0.", "Copy"},
	{"jdk17-g1", "17.0.", "G1 young collection pauses"},
	{"jdk17-serial", "17.0.", "Serial young collection pauses"},
	{"jdk17-parallel", "17.0.", "Parallel young collection pauses"},
	{"jdk17-shenandoah", "17.0.", "Shenandoah partial"},
	{"jdk21-g1", "21.0.", "G1 young collection pauses"},
	{"jdk21-zgc", "21.0.", "Z concurrent cycle pauses"},
	{"jdk21-zgc-generational", "21.0.", "ZGC minor collection pauses"},
}

func TestParseSamples(t *testing.T) {
	for _, s := range samples {
		t.Run(s.name, func(t *testing.T) {
			p, err := Parse(sample(t, s.name))
			if err != nil {
				t.Fatal(err)
			}
			// JDK 8, 11, 17 and 21 all write format 2.0 in the host byte order.
			if p.Major != 2 || p.Minor != 0 || p.BigEndian {
				t.Errorf("header = %d.%d bigEndian=%v; want 2.0 little endian", p.Major, p.Minor, p.BigEndian)
			}
			if len(p.Entries) < 100 {
				t.Errorf("only %d entries", len(p.Entries))
			}
			version, ok := p.Text("java.property.java.version")
			if !ok || !strings.HasPrefix(version, s.version) {
				t.Errorf("java.version = %q, %v; want prefix %q", version, ok, s.version)
			}
			command, ok := p.Text("sun.rt.javaCommand")
			if !ok || FirstWord(command) != "com.example.sample.Sample" {
				t.Errorf("first word of javaCommand = %q, %v", FirstWord(command), ok)
			}
			capabilities, ok := p.Text("sun.rt.jvmCapabilities")
			if !ok || len(capabilities) != 64 {
				t.Errorf("jvmCapabilities = %q, %v; want 64 flags", capabilities, ok)
			}
			if n, ok := p.Long("java.threads.live"); !ok || n < 5 {
				t.Errorf("java.threads.live = %d, %v", n, ok)
			}
			if _, ok := p.Long("java.property.java.version"); ok {
				t.Error("a string counter was returned as a number")
			}
			if _, ok := p.Text("java.threads.live"); ok {
				t.Error("a numeric counter was returned as a string")
			}
		})
	}
}

func TestStringHidesValues(t *testing.T) {
	p, err := Parse(sample(t, "jdk17-g1"))
	if err != nil {
		t.Fatal(err)
	}
	for _, text := range []string{p.String(), (*PerfData)(nil).String()} {
		for _, secret := range []string{"--note=hello", "com.example", "-Xmx256m", "/opt/java"} {
			if strings.Contains(text, secret) {
				t.Errorf("String() = %q contains %q", text, secret)
			}
		}
	}
}

func TestFirstWord(t *testing.T) {
	for in, want := range map[string]string{
		"com.example.App":                      "com.example.App",
		"com.example.App --password=hunter2":   "com.example.App",
		"/opt/app.jar --spring.datasource=x y": "/opt/app.jar",
		"":                                     "",
		" leading":                             "",
	} {
		if got := FirstWord(in); got != want {
			t.Errorf("FirstWord(%q) = %q; want %q", in, got, want)
		}
	}
}

// builder writes hsperfdata files the way HotSpot lays them out.
type builder struct {
	order   binary.ByteOrder
	entries [][]byte
}

func newBuilder(order binary.ByteOrder) *builder { return &builder{order: order} }

func align8(n int) int { return (n + 7) &^ 7 }

func (b *builder) entry(name string, vectorLength int, dataType, units byte, data []byte) []byte {
	nameOffset := 20
	dataOffset := align8(nameOffset + len(name) + 1)
	length := align8(dataOffset + len(data))
	e := make([]byte, length)
	b.order.PutUint32(e[0:], uint32(length))
	b.order.PutUint32(e[4:], uint32(nameOffset))
	b.order.PutUint32(e[8:], uint32(vectorLength))
	e[12], e[14], e[15] = dataType, units, 3
	b.order.PutUint32(e[16:], uint32(dataOffset))
	copy(e[nameOffset:], name)
	copy(e[dataOffset:], data)
	return e
}

func (b *builder) long(name string, value int64) *builder {
	data := make([]byte, 8)
	b.order.PutUint64(data, uint64(value))
	b.entries = append(b.entries, b.entry(name, 0, 'J', 1, data))
	return b
}

func (b *builder) text(name, value string) *builder {
	b.entries = append(b.entries, b.entry(name, len(value)+1, 'B', 5, append([]byte(value), 0)))
	return b
}

func (b *builder) bytes() []byte {
	body := bytes.Join(b.entries, nil)
	header := make([]byte, 32)
	copy(header, []byte{0xca, 0xfe, 0xc0, 0xc0})
	if b.order == binary.LittleEndian {
		header[4] = 1
	}
	header[5], header[6], header[7] = 2, 0, 1
	b.order.PutUint32(header[8:], uint32(32+len(body)))
	b.order.PutUint32(header[24:], 32)
	b.order.PutUint32(header[28:], uint32(len(b.entries)))
	return append(header, body...)
}

func TestParseSyntheticByteOrders(t *testing.T) {
	for _, order := range []binary.ByteOrder{binary.LittleEndian, binary.BigEndian} {
		data := newBuilder(order).long("java.threads.live", 12).text("java.property.java.version", "17.0.1").bytes()
		p, err := Parse(data)
		if err != nil {
			t.Fatalf("%v: %v", order, err)
		}
		if p.BigEndian != (order == binary.BigEndian) {
			t.Errorf("%v: BigEndian = %v", order, p.BigEndian)
		}
		if n, ok := p.Long("java.threads.live"); !ok || n != 12 {
			t.Errorf("%v: live = %d, %v", order, n, ok)
		}
		if s, ok := p.Text("java.property.java.version"); !ok || s != "17.0.1" {
			t.Errorf("%v: version = %q, %v", order, s, ok)
		}
	}
}

func TestParseIgnoresUnknownEntryTypesAndKeepsFirstDuplicate(t *testing.T) {
	b := newBuilder(binary.LittleEndian)
	b.long("a", 1).long("a", 2)
	// An int vector is neither a long nor a string: it is skipped, not an error.
	b.entries = append(b.entries, b.entry("vec", 2, 'I', 1, make([]byte, 8)))
	b.long("b", 3)
	p, err := Parse(b.bytes())
	if err != nil {
		t.Fatal(err)
	}
	if n, _ := p.Long("a"); n != 1 {
		t.Errorf("a = %d; want the first definition", n)
	}
	if _, ok := p.Entries["vec"]; ok {
		t.Error("an int vector was kept")
	}
	if n, ok := p.Long("b"); !ok || n != 3 {
		t.Errorf("b = %d, %v", n, ok)
	}
}

func TestParseRejectsMalformedFiles(t *testing.T) {
	valid := func() []byte {
		return newBuilder(binary.LittleEndian).long("java.threads.live", 7).text("java.property.java.version", "17.0.1").bytes()
	}
	// Offsets of the first entry's fields (the entry starts at 32).
	const entry = 32
	patch := func(offset int, value uint32) func([]byte) {
		return func(d []byte) { binary.LittleEndian.PutUint32(d[offset:], value) }
	}
	cases := []struct {
		name   string
		mutate func([]byte) []byte
		want   error
	}{
		{"bad magic", func(d []byte) []byte { d[0] = 0; return d }, ErrNotPerfData},
		{"unknown byte order", func(d []byte) []byte { d[4] = 7; return d }, ErrUnsupported},
		{"major version 3", func(d []byte) []byte { d[5] = 3; return d }, ErrUnsupported},
		{"major version 1", func(d []byte) []byte { d[5] = 1; return d }, ErrUnsupported},
		{"not accessible", func(d []byte) []byte { d[7] = 0; return d }, ErrNotReady},
		{"empty", func([]byte) []byte { return nil }, ErrNotPerfData},
		{"shorter than the prologue", func(d []byte) []byte { return d[:20] }, ErrCorrupt},
		{"used beyond the file", func(d []byte) []byte { patch(8, uint32(len(d)+1))(d); return d }, ErrCorrupt},
		{"used smaller than the prologue", func(d []byte) []byte { patch(8, 16)(d); return d }, ErrCorrupt},
		{"used negative", func(d []byte) []byte { patch(8, 0x80000000)(d); return d }, ErrCorrupt},
		{"entry offset beyond used", func(d []byte) []byte { patch(24, uint32(len(d)+8))(d); return d }, ErrCorrupt},
		{"entry offset inside the prologue", func(d []byte) []byte { patch(24, 8)(d); return d }, ErrCorrupt},
		{"more entries than the file holds", func(d []byte) []byte { patch(28, 1<<30)(d); return d }, ErrCorrupt},
		{"negative entry count", func(d []byte) []byte { patch(28, 0xffffffff)(d); return d }, ErrCorrupt},
		{"entry length zero", func(d []byte) []byte { patch(entry, 0)(d); return d }, ErrCorrupt},
		{"entry length below the header", func(d []byte) []byte { patch(entry, 16)(d); return d }, ErrCorrupt},
		{"entry length beyond used", func(d []byte) []byte { patch(entry, uint32(len(d)))(d); return d }, ErrCorrupt},
		{"entry length negative", func(d []byte) []byte { patch(entry, 0xfffffff8)(d); return d }, ErrCorrupt},
		{"name offset inside the header", func(d []byte) []byte { patch(entry+4, 4)(d); return d }, ErrCorrupt},
		{"name offset beyond the entry", func(d []byte) []byte { patch(entry+4, 4096)(d); return d }, ErrCorrupt},
		{"name without terminator", func(d []byte) []byte {
			// Fill the entry from the name on with non-zero bytes.
			end := entry + int(binary.LittleEndian.Uint32(d[entry:]))
			for i := entry + 20; i < end; i++ {
				d[i] = 'x'
			}
			return d
		}, ErrCorrupt},
		{"empty name", func(d []byte) []byte { d[entry+20] = 0; return d }, ErrCorrupt},
		{"name with a control character", func(d []byte) []byte { d[entry+21] = '\n'; return d }, ErrCorrupt},
		{"data offset beyond the entry", func(d []byte) []byte { patch(entry+16, 4096)(d); return d }, ErrCorrupt},
		{"data offset inside the header", func(d []byte) []byte { patch(entry+16, 8)(d); return d }, ErrCorrupt},
		{"data offset negative", func(d []byte) []byte { patch(entry+16, 0xfffffff8)(d); return d }, ErrCorrupt},
		{"long that does not fit the entry", func(d []byte) []byte {
			patch(entry+16, binary.LittleEndian.Uint32(d[entry:])-4)(d)
			return d
		}, ErrCorrupt},
		{"long with a vector length", func(d []byte) []byte { patch(entry+8, 3)(d); return d }, ErrCorrupt},
		{"string longer than the entry", func(d []byte) []byte {
			second := entry + int(binary.LittleEndian.Uint32(d[entry:]))
			patch(second+8, 1<<20)(d)
			return d
		}, ErrCorrupt},
		{"string length overflowing 32 bits", func(d []byte) []byte {
			second := entry + int(binary.LittleEndian.Uint32(d[entry:]))
			patch(second+8, 0x7fffffff)(d)
			return d
		}, ErrCorrupt},
		{"string with negative length", func(d []byte) []byte {
			second := entry + int(binary.LittleEndian.Uint32(d[entry:]))
			patch(second+8, 0x80000001)(d)
			return d
		}, ErrCorrupt},
	}
	if _, err := Parse(valid()); err != nil {
		t.Fatalf("the unmodified file does not parse: %v", err)
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			p, err := Parse(tc.mutate(valid()))
			if !errors.Is(err, tc.want) {
				t.Fatalf("err = %v, parsed = %v; want %v", err, p, tc.want)
			}
		})
	}
}

func TestParseRejectsTruncatedSamples(t *testing.T) {
	data := sample(t, "jdk17-g1")
	used := int(binary.LittleEndian.Uint32(data[8:]))
	for n := 0; n < used; n += 61 {
		if p, err := Parse(data[:n]); err == nil {
			t.Fatalf("truncation to %d of %d bytes parsed: %v", n, used, p)
		}
	}
}

func TestParseRejectsOversizedInput(t *testing.T) {
	data := make([]byte, MaxFileSize+1)
	copy(data, sample(t, "jdk17-g1"))
	if _, err := Parse(data); !errors.Is(err, ErrCorrupt) {
		t.Fatalf("err = %v; want ErrCorrupt", err)
	}
}

func FuzzParse(f *testing.F) {
	for _, s := range samples {
		f.Add(sample(f, s.name))
	}
	f.Add(newBuilder(binary.BigEndian).long("java.threads.live", 1).bytes())
	f.Fuzz(func(t *testing.T, data []byte) {
		p, err := Parse(data)
		if err != nil {
			return
		}
		for name, e := range p.Entries {
			if name != e.Name || (e.Kind != KindLong && e.Kind != KindText) {
				t.Fatalf("inconsistent entry %q: %+v", name, e)
			}
		}
		_, _ = p.Summary()
	})
}
